import json,re,textfix
f=json.load(open('features_out.json'))
M={
'barbarian-rage':"You can imbue yourself with a primal power called Rage, a force that grants you extraordinary might and resilience. You can enter it as a Bonus Action if you aren't wearing Heavy armor.\nYou can enter your Rage the number of times shown for your Barbarian level in the Rages column of the Barbarian Features table. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest.\nWhile active, your Rage follows the rules below.\nDamage Resistance. You have Resistance to Bludgeoning, Piercing, and Slashing damage.\nRage Damage. When you make an attack using Strength—with either a weapon or an Unarmed Strike—and deal damage to the target, you gain a bonus to the damage that increases as you gain levels as a Barbarian, as shown in the Rage Damage column of the Barbarian Features table.\nStrength Advantage. You have Advantage on Strength checks and Strength saving throws.\nNo Concentration or Spells. You can't maintain Concentration, and you can't cast spells.\nDuration. The Rage lasts until the end of your next turn, and it ends early if you don Heavy armor or have the Incapacitated condition. If your Rage is still active on your next turn, you can extend the Rage for another round by making an attack roll against an enemy, forcing an enemy to make a saving throw, or taking a Bonus Action to extend your Rage. Each time the Rage is extended, it lasts until the end of your next turn. You can maintain a Rage for up to 10 minutes.",
'cleric-light-domain-improved-warding-flare':"You regain all expended uses of your Warding Flare when you finish a Short or Long Rest.\nIn addition, whenever you use Warding Flare, you can give the target of the triggering attack a number of Temporary Hit Points equal to 2d6 plus your Wisdom modifier.",
'fighter-eldritch-knight-spellcasting':"You have learned to cast spells. Intelligence is your spellcasting ability for these spells, and you can use an Arcane Focus as a Spellcasting Focus.\nCantrips. You know two cantrips of your choice from the Wizard spell list. You know one more at Fighter level 10.\nSpell Slots. The Eldritch Knight Spellcasting table shows how many spell slots you have; you regain all expended slots when you finish a Long Rest.\nPrepared Spells. You prepare three level 1 Wizard spells, and the number increases as you gain Fighter levels. Whenever you gain a Fighter level, you can replace one spell on your list with another Wizard spell for which you have spell slots.",
'monk-unarmored-movement':"Your speed increases by 10 feet while you aren't wearing armor or wielding a Shield. This bonus increases when you reach certain Monk levels, as shown on the Monk Features table.",
'monk-monk-subclass':"You gain a Monk subclass of your choice. The Warrior of Mercy, Warrior of Shadow, Warrior of the Elements, and Warrior of the Open Hand subclasses are detailed after this class's description. A subclass is a specialization that grants you features at certain Monk levels. For the rest of your career, you gain each of your subclass's features that are of your Monk level or lower.",
'ranger-roving':"Your Speed increases by 10 feet while you aren't wearing Heavy armor. You also have a Climb Speed and a Swim Speed equal to your Speed.",
'ranger-fey-wanderer-beguiling-twist':"The magic of the Feywild guards your mind. You have Advantage on saving throws to avoid or end the Charmed or Frightened condition.\nIn addition, whenever you or a creature you can see within 120 feet of you succeeds on a saving throw to avoid or end the Charmed or Frightened condition, you can take a Reaction to force a different creature you can see within 120 feet of yourself to make a Wisdom saving throw against your spell save DC. On a failed save, the target is Charmed or Frightened (your choice) for 1 minute. The target repeats the save at the end of each of its turns, ending the effect on itself on a success.",
'sorcerer-draconic-sorcery-dragon-companion':"You can cast Summon Dragon without a Material component. You can also cast it once without a spell slot, and you regain the ability to cast it in this way when you finish a Long Rest.\nWhenever you start casting the spell, you can modify it so that it doesn't require Concentration. If you do so, the spell's duration becomes 1 minute for that casting.",
'fighter-battle-master-ultimate-combat-superiority':"Your Superiority Die becomes a d12.",
'fighter-battle-master-improved-combat-superiority':"Your Superiority Die becomes a d10.",
}
for x in f:
    if x['id'] in M: x['description']=M[x['id']]
    x['description']=textfix.fix(x['description']).replace('toO Hit','to 0 Hit')
    sents=re.split(r"(?<=[.!?])\s",x['description'].replace('\n',' '))
    x['summary']=' '.join(sents[:2])[:320]
json.dump(f,open('../../data/class-features.json','w'),indent=0,ensure_ascii=False)
o=json.load(open('class_options.json'))
json.dump(o,open('../../data/class-options.json','w'),indent=0,ensure_ascii=False)
print(len(f), sum(1 for x in f if len(x['description'])<30))
